function expand(pairs) {
  const ring = [];
  for (const [lat, lng] of pairs) ring.push({ lat, lng });
  return ring;
}

export const FAMOUS_PARKS = RAWS.map((park) => ({
  id: park.id,
  source: park.source,
  categoryId: park.categoryId,
  name: park.name,
  subtitle: park.subtitle,
  address: park.address,
  lat: park.lat,
  lng: park.lng,
  perimeter: true,
  zoneNote: PARK_NOTE,
  bounds: park.bounds,
  polygons: park.polygons.map((poly) => ({
    outer: expand(poly.outer),
    holes: (poly.holes || []).map(expand),
  })),
  meta: { acres: park.acres },
}));

export function famousParksInView(bounds) {
  if (!bounds) return [];
  const pad = 0.004;
  return FAMOUS_PARKS.filter((park) => {
    const b = park.bounds;
    return !(
      bounds.east < b.west - pad ||
      bounds.west > b.east + pad ||
      bounds.north < b.south - pad ||
      bounds.south > b.north + pad
    );
  });
}
